L20_1.m_Talk_KOREA = "솔로베의 꽃차는 정말 향긋하구나. 백화점에서 늘 맡던 화장품 냄새만큼은 아니지만 말이야."
L20_1.m_fTalkTime = 0.03
L20_1.m_ImageName = "ANIV2_03"
L20_1.m_Talk_JPN = "ソロベーの花茶は本当にいい香りがする。いつもデパートで嗅いでいた化粧品の匂いほどではないけど。"
L20_1.m_Talk_ENG = "Solovey's flower tea is really fragrant. It's not quite as strong as the perfume smell I used to smell at the department store, though."
L20_1.m_Talk_TWN = "蘇羅薇的花茶真的很香，雖然沒有百貨公司裡常聞到的化妝品味道那麼濃郁。"
L20_1.m_Talk_SCN = "索洛贝的花茶真的很香，虽然没有百货商店里常闻到的化妆品味道那么浓郁。"
L20_1.m_Talk_DEU = "Solovey's flower tea is really fragrant. It's not quite as strong as the perfume smell I used to smell at the department store, though."
L20_1.m_Talk_FRA = "Solovey's flower tea is really fragrant. It's not quite as strong as the perfume smell I used to smell at the department store, though."
