L21_1.m_Talk_KOREA = "전 그 냄새 별로에요. 정원에선 그보다 향긋한 꽃이 훨씬 많은 걸요."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "私はその匂い苦手です。庭園にはそれよりいい香りのお花がもっとたくさんあります。"
L21_1.m_Talk_ENG = "I don't like that smell much. There are far more fragrant flowers in the garden."
L21_1.m_Talk_TWN = "我不太喜歡那個味道，我覺得花園裡的花比較香。"
L21_1.m_Talk_SCN = "我不太喜欢那个味道。花园里有比那香得多的花呢。"
L21_1.m_Talk_DEU = "I don't like that smell much. There are far more fragrant flowers in the garden."
L21_1.m_Talk_FRA = "I don't like that smell much. There are far more fragrant flowers in the garden."
