L23_1.m_Talk_KOREA = "그치만 다신 못 돌아갈 거예요. 패리가 돌아가는 문이 닫혔다고 그랬거든요."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "それが、もう二度と戻れないんです。扉が閉ざされたって、パリーが言ってましたから。"
L23_1.m_Talk_ENG = "But I'll never be able to go back. Parry said the door to return is closed."
L23_1.m_Talk_TWN = "但是再也回不去了，佩瑞是這麼說的。"
L23_1.m_Talk_SCN = "但是再也回不去了。佩莉是这么说的。"
L23_1.m_Talk_DEU = "But I'll never be able to go back. Parry said the door to return is closed."
L23_1.m_Talk_FRA = "But I'll never be able to go back. Parry said the door to return is closed."
