L24_1 = "APPRAISER_NPC_BLACK_MARKET"
L23_1.m_CharStrID = L24_1
L24_1 = "미량의 침식파를 발산하는 걸로 봐선 이면세계 물건이 맞습니다. 모조품은 아니네요."
