L23_1.m_fTalkTime = 0.03
L24_1 = "ANIV2_02"
L23_1.m_ImageName = L24_1
L24_1 = "微量の侵食波を発していますので間違いなく裏世界の物です。偽物ではありません。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "It's emitting trace amounts of Corruption ray, so this is definitely an item from the Counterside. It's not a counterfeit."
L23_1.m_Talk_ENG = L24_1
L24_1 = "從散發出微量的侵蝕波來看，這確實是異界的物品。不是仿製品呢。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "从散发出微量的侵蚀波来看，这确实是异界的物品。不是仿制品呢。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "It's emitting trace amounts of Corruption ray, so this is definitely an item from the Counterside. It's not a counterfeit."
