L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "APPRAISER_NPC_BLACK_MARKET"
L24_1.m_CharStrID = L25_1
L25_1 = "겉은 돌처럼 생겼지만 이 형체를 구성하는 건 현실엔 없는 원소입니다. 우리가 아는 관리국 기조에 따르면 아티팩트의 기준에도 부합하죠."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "ANIV2_02"
L24_1.m_ImageName = L25_1
L25_1 = "石のように見えますが、現実に存在しない元素で構成されています。私たちが知っている管理局の基調によればアーティファクトの基準にも合致します。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "It looks like stone on the outside, but the elements making up this form don't exist in the Normalside. According to the Administration's standards, this qualifies as an Artifact."
L24_1.m_Talk_ENG = L25_1
L25_1 = "外表看起來像石頭，但構成這種形態的元素在現實中並不存在。根據我們所知的管理局基調，這也符合神器的標準。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "外表看起来像石头，但构成这种形态的元素在现实中并不存在。根据我们所知的管理局基调，这也符合神器的标准。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "It looks like stone on the outside, but the elements making up this form don't exist in the Normalside. According to the Administration's standards, this qualifies as an Artifact."
L24_1.m_Talk_DEU = L25_1
L25_1 = "It looks like stone on the outside, but the elements making up this form don't exist in the Normalside. According to the Administration's standards, this qualifies as an Artifact."
L24_1.m_Talk_FRA = L25_1
